with parsed as (select id, created_at, coupon_codes, attributes['utm_source'] as utm_source, transform(filter(items, item -> item.promo is not null), item -> struct(item.product_id as pid, round(item.price * 0.9, 2) as discounted_price)) as promo_lines, transform(items, item -> item.product_id) as product_ids from carts where created_at < '2023-09-01') select date_trunc('day', created_at) as activity_day, min(created_at) as first_seen, max(created_at) as last_created_at, min(created_at) as first_seen_2, count(*) as cnt, count(*) as cnt_2, count(*) as row_count from parsed group by date_trunc('day', created_at) order by cnt_2 asc;
